import { spawnSync } from "node:child_process";
import { chmod, cp, mkdir, mkdtemp, readFile, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";
import { pathToFileURL } from "node:url";
import { verifyNodeInstaller } from "./verify-node-installer.mjs";

export async function buildNodePkg(input) {
  const staged = resolve(input.stagedRoot), output = resolve(input.output);
  if (!/^\d+\.\d+\.\d+(?:-[0-9A-Za-z.+~]+)?$/.test(input.version)) throw new Error("node_pkg_version_is_invalid");
  const layout = await verifyNodeInstaller(staged); if (layout.target !== "macos-arm64") throw new Error("node_pkg_layout_target_mismatch");
  const root = `${output}.root`; await rm(root, { recursive: true, force: true }); await rm(output, { force: true });
  await cp(staged, join(root, "Library/Application Support/Mycellios/Product"), { recursive: true, errorOnExist: true, force: false });
  await materializeMacPairingApp(root);
  const result = spawnSync("pkgbuild", ["--root", root, "--identifier", "io.mycellios.node", "--version", input.version, "--install-location", "/", output], { encoding: "utf8", shell: false,
    env: { ...process.env, SOURCE_DATE_EPOCH: input.sourceDateEpoch ?? "0" } });
  if (result.error) throw result.error; if (result.status !== 0) throw new Error(`node_pkg_build_failed:${result.stderr.trim()}`);
  await rm(root, { recursive: true, force: true }); return { output, layout };
}

export async function materializeMacPairingApp(rootValue) {
  const contents = join(resolve(rootValue), "Applications/Mycellios Pairing.app/Contents"), executable = join(contents, "Resources/pair-mycellios");
  const sourceRoot = await mkdtemp(join(tmpdir(), "mycellios-pairing-compile-"));
  await mkdir(join(contents, "../.."), { recursive: true });
  try {
    const source = join(sourceRoot, "handler.applescript");
    await writeFile(source, renderMacPairingOpenScript("/Applications/Mycellios Pairing.app/Contents/Resources/pair-mycellios"), { mode: 0o600 });
    runPairingTool("/usr/bin/osacompile", ["-o", join(contents, ".."), source]);
  } finally { await rm(sourceRoot, { recursive: true, force: true }); }
  const plist = join(contents, "Info.plist");
  const executableName = runPairingTool("/usr/bin/plutil", ["-extract", "CFBundleExecutable", "raw", "-o", "-", plist]).trim();
  if (executableName !== "droplet") throw new Error("node_pkg_pairing_executable_is_invalid");
  for (const key of ["CFBundleIdentifier", "CFBundleName", "CFBundleDocumentTypes", "LSBackgroundOnly"]) {
    const result = spawnSync("/usr/bin/plutil", ["-remove", key, plist], { encoding: "utf8", timeout: 30_000 });
    if (result.error) throw result.error;
  }
  runPairingTool("/usr/bin/plutil", ["-insert", "CFBundleIdentifier", "-string", "io.mycellios.pairing", plist]);
  runPairingTool("/usr/bin/plutil", ["-insert", "CFBundleName", "-string", "Mycellios Pairing", plist]);
  runPairingTool("/usr/bin/plutil", ["-insert", "LSBackgroundOnly", "-bool", "true", plist]);
  runPairingTool("/usr/bin/plutil", ["-insert", "CFBundleDocumentTypes", "-json", JSON.stringify([{
    CFBundleTypeName: "Mycellios Enrollment", CFBundleTypeRole: "Viewer", LSHandlerRank: "Owner",
    CFBundleTypeExtensions: ["mycellios-enrollment"], CFBundleTypeMIMETypes: ["application/vnd.mycellios.enrollment+json"],
  }]), plist]);
  // Preserve the archive's existing textual document-owner contract without changing plist values.
  await writeFile(plist, (await readFile(plist, "utf8")).replace(/<\/key>\s*<string>/g, "</key><string>"), { mode: 0o644 });
  await writeFile(executable, ["#!/bin/sh", "set -eu", 'exec "/Library/Application Support/Mycellios/Product/bin/node" "/Library/Application Support/Mycellios/Product/app/node/macos-pairing-main.js" "$1"', ""].join("\n"), { mode: 0o755 });
  await chmod(executable, 0o755);
  runPairingTool("/usr/bin/codesign", ["--force", "--sign", "-", "--timestamp=none", join(contents, "..")]);
  runPairingTool("/usr/bin/codesign", ["--verify", "--strict", "--deep", join(contents, "..")]);
}

// Build-time renderer; the shipped application has no environment or test executor override.
export function renderMacPairingOpenScript(executable) {
  const command = `'${executable.replaceAll("'", "'\\''")}' `;
  const literal = `"${command.replaceAll("\\", "\\\\").replaceAll('"', '\\"')}"`;
  return ["on open incomingDocuments", "repeat with incomingDocument in incomingDocuments",
    `do shell script ${literal} & quoted form of POSIX path of incomingDocument`,
    "end repeat", "quit", "end open"].join("\n");
}
function runPairingTool(file, args) {
  const result = spawnSync(file, args, { encoding: "utf8", shell: false, timeout: 30_000, maxBuffer: 8192 });
  if (result.error) throw result.error;
  if (result.status !== 0) throw new Error(`node_pkg_pairing_tool_failed:${file}:${result.stderr.trim()}`);
  return result.stdout;
}

async function main(argv) { const values = Object.fromEntries(argv.map((argument) => { const match = /^--([^=]+)=(.+)$/.exec(argument); if (!match) throw new Error(`node_pkg_argument_is_invalid:${argument}`); return [match[1], match[2]]; }));
  for (const key of ["staged-root", "output", "version"]) if (!values[key]) throw new Error(`node_pkg_argument_is_missing:${key}`);
  await buildNodePkg({ stagedRoot: values["staged-root"], output: values.output, version: values.version, sourceDateEpoch: values["source-date-epoch"] }); }
if (import.meta.url === pathToFileURL(process.argv[1] ?? "").href) await main(process.argv.slice(2));

import { spawnSync } from "node:child_process";
import { mkdtemp, readFile, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";
import { pathToFileURL } from "node:url";
import { renderMacPairingOpenScript } from "./build-node-pkg.mjs";
import { assertInstallerPackageTreeMatches } from "./verify-installer-package-tree.mjs";

export async function verifyNodePkg(input) {
  const root = await mkdtemp(join(tmpdir(), "mycellios-node-pkg-verify-")), expanded = join(root, "expanded");
  try {
    const result = spawnSync("pkgutil", ["--expand-full", resolve(input.pkg), expanded], { encoding: "utf8", shell: false });
    if (result.error) throw result.error; if (result.status !== 0) throw new Error("node_pkg_expand_failed");
    const payload = join(expanded, "Payload");
    await assertInstallerPackageTreeMatches(resolve(input.stagedRoot), join(payload, "Library/Application Support/Mycellios/Product"));
    const plist = await readFile(join(payload, "Applications/Mycellios Pairing.app/Contents/Info.plist"), "utf8");
    const launcher = await readFile(join(payload, "Applications/Mycellios Pairing.app/Contents/Resources/pair-mycellios"), "utf8");
    if (!plist.includes("mycellios-enrollment") || !plist.includes("io.mycellios.pairing") || !launcher.includes("macos-pairing-main.js") || !plist.includes("<string>droplet</string>")) {
      throw new Error("node_pkg_pairing_application_is_invalid");
    }
    const app = join(payload, "Applications/Mycellios Pairing.app");
    const signature = spawnSync("/usr/bin/codesign", ["--verify", "--strict", "--deep", app], { encoding: "utf8", timeout: 30_000 });
    const script = spawnSync("/usr/bin/osadecompile", [join(app, "Contents/Resources/Scripts/main.scpt")], { encoding: "utf8", timeout: 30_000, maxBuffer: 8192 });
    const normalize = value => value.split(/\r?\n/).map(line => line.trim()).filter(Boolean).join("\n");
    if (signature.error || signature.status !== 0 || script.error || script.status !== 0 ||
        normalize(script.stdout) !== normalize(renderMacPairingOpenScript("/Applications/Mycellios Pairing.app/Contents/Resources/pair-mycellios"))) {
      throw new Error("node_pkg_pairing_applet_is_invalid");
    }
    return { identifier: "io.mycellios.node", version: input.version };
  } finally { await rm(root, { recursive: true, force: true }); }
}

if (import.meta.url === pathToFileURL(process.argv[1] ?? "").href) {
  const values = Object.fromEntries(process.argv.slice(2).map((argument) => { const match = /^--([^=]+)=(.+)$/.exec(argument); if (!match) throw new Error(`node_pkg_verify_argument_is_invalid:${argument}`); return [match[1], match[2]]; }));
  for (const key of ["pkg", "staged-root", "version"]) if (!values[key]) throw new Error(`node_pkg_verify_argument_is_missing:${key}`);
  await verifyNodePkg({ pkg: values.pkg, stagedRoot: values["staged-root"], version: values.version }); process.stdout.write(`Native node PKG verified: ${values.pkg}\n`);
}

import { spawn } from "node:child_process";
import { randomBytes } from "node:crypto";
import { mkdir, open, readFile, rename, rm } from "node:fs/promises";
import { dirname, join, resolve } from "node:path";
import { z } from "zod";
import {
  generateWorkerAdmissionCredential,
  parseWorkerAdmissionCredential,
  workerAdmissionSigner,
  type WorkerAdmissionCredential,
  type WorkerAdmissionSigner,
} from "../worker/admission-credential.js";

const metadataSchema = z.object({
  schema: z.literal("mycellios-node-identity/1"),
  identityId: z.string().regex(/^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$/),
  provider: z.string().min(1).max(100),
  secretReference: z.string().regex(/^[A-Za-z0-9._:-]{1,200}$/),
  algorithm: z.literal("ed25519"),
  publicKeySpki: z.string().min(40).max(256),
  createdAt: z.string().datetime(),
}).strict();

export interface ProtectedSecretStore {
  readonly provider: string;
  get(reference: string): Promise<string | null>;
  set(reference: string, value: string): Promise<void>;
  delete(reference: string): Promise<void>;
}

export interface SecretCommandResult {
  code: number;
  stdout: string;
}

export type SecretCommandRunner = (
  executable: string,
  arguments_: readonly string[],
  stdin?: string,
) => Promise<SecretCommandResult>;

export class NodeIdentityStore {
  readonly metadataPath: string;

  constructor(
    metadataPath: string,
    private readonly secrets: ProtectedSecretStore,
    private readonly options: { allowLegacyMigration?: boolean } = {},
  ) {
    this.metadataPath = resolve(metadataPath);
  }

  async loadOrCreate(identityId: string): Promise<WorkerAdmissionSigner> {
    const existing = await this.readMetadata(identityId);
    if (existing) {
      if (existing.identityId !== identityId) throw new Error("node_identity_id_mismatch");
      if (existing.provider !== this.secrets.provider) throw new Error("node_identity_provider_mismatch");
      const value = await this.secrets.get(existing.secretReference);
      if (!value) throw new Error("node_identity_protected_secret_is_missing");
      const credential = parseWorkerAdmissionCredential(JSON.parse(value) as unknown);
      if (credential.publicKeySpki !== existing.publicKeySpki) {
        throw new Error("node_identity_public_key_mismatch");
      }
      return workerAdmissionSigner(credential);
    }

    const credential = generateWorkerAdmissionCredential();
    const reference = `node-${identityId}-${randomBytes(12).toString("hex")}`;
    await this.secrets.set(reference, JSON.stringify(credential));
    try {
      await this.writeMetadata({
        schema: "mycellios-node-identity/1",
        identityId,
        provider: this.secrets.provider,
        secretReference: reference,
        algorithm: "ed25519",
        publicKeySpki: credential.publicKeySpki,
        createdAt: new Date().toISOString(),
      });
    } catch (error) {
      await this.secrets.delete(reference).catch(() => undefined);
      throw error;
    }
    return workerAdmissionSigner(credential);
  }

  private async readMetadata(identityId: string): Promise<z.infer<typeof metadataSchema> | null> {
    let document: unknown;
    try { document = JSON.parse(await readFile(this.metadataPath, "utf8")); } catch (error) {
      if ((error as NodeJS.ErrnoException).code === "ENOENT") return null;
      throw new Error("node_identity_metadata_is_invalid", { cause: error });
    }
    const metadata = metadataSchema.safeParse(document);
    if (metadata.success) return metadata.data;

    let legacy: WorkerAdmissionCredential;
    try { legacy = parseWorkerAdmissionCredential(document); } catch (error) {
      throw new Error("node_identity_metadata_is_invalid", { cause: error });
    }
    if (this.options.allowLegacyMigration !== true) {
      throw new Error("node_identity_legacy_migration_confirmation_required");
    }
    const reference = `node-${identityId}-${randomBytes(12).toString("hex")}`;
    await this.secrets.set(reference, JSON.stringify(legacy));
    const migrated = metadataSchema.parse({
      schema: "mycellios-node-identity/1",
      identityId,
      provider: this.secrets.provider,
      secretReference: reference,
      algorithm: "ed25519",
      publicKeySpki: legacy.publicKeySpki,
      createdAt: new Date().toISOString(),
    });
    try {
      await this.writeMetadata(migrated);
    } catch (error) {
      await this.secrets.delete(reference).catch(() => undefined);
      throw error;
    }
    return migrated;
  }

  private async writeMetadata(value: z.infer<typeof metadataSchema>): Promise<void> {
    await mkdir(dirname(this.metadataPath), { recursive: true, mode: 0o700 });
    const temporary = `${this.metadataPath}.tmp-${process.pid}-${randomBytes(6).toString("hex")}`;
    try {
      const file = await open(temporary, "wx", 0o600);
      try {
        await file.writeFile(`${JSON.stringify(value, null, 2)}\n`, "utf8");
        await file.sync();
      } finally {
        await file.close();
      }
      await rename(temporary, this.metadataPath);
    } finally {
      await rm(temporary, { force: true });
    }
  }
}

export class LinuxSecretToolStore implements ProtectedSecretStore {
  readonly provider = "linux-secret-service";

  constructor(private readonly run: SecretCommandRunner = runSecretCommand) {}

  async get(reference: string): Promise<string | null> {
    const result = await this.run("secret-tool", ["lookup", "application", "mycellios", "identity", reference]);
    if (result.code === 1) return null;
    if (result.code !== 0) throw new Error("node_identity_secret_service_lookup_failed");
    return result.stdout.replace(/\r?\n$/, "");
  }

  async set(reference: string, value: string): Promise<void> {
    const result = await this.run("secret-tool", [
      "store",
      "--label=mycellios node identity",
      "application",
      "mycellios",
      "identity",
      reference,
    ], value);
    if (result.code !== 0) throw new Error("node_identity_secret_service_store_failed");
  }

  async delete(reference: string): Promise<void> {
    const result = await this.run("secret-tool", ["clear", "application", "mycellios", "identity", reference]);
    if (result.code !== 0 && result.code !== 1) {
      throw new Error("node_identity_secret_service_delete_failed");
    }
  }
}

/** Persistent headless identity storage encrypted by systemd-creds (TPM2/host key). */
export class LinuxSystemdCredentialStore implements ProtectedSecretStore {
  readonly provider = "linux-systemd-creds";
  private readonly root: string;

  constructor(root: string, private readonly run: SecretCommandRunner = runSecretCommand) {
    this.root = resolve(root);
  }

  async get(reference: string): Promise<string | null> {
    const path = this.secretPath(reference);
    try { await readFile(path); } catch (error) {
      if ((error as NodeJS.ErrnoException).code === "ENOENT") return null;
      throw error;
    }
    const result = await this.run("systemd-creds", ["decrypt", `--name=${reference}`, path, "-"]);
    if (result.code !== 0) throw new Error("node_identity_systemd_creds_decrypt_failed");
    return result.stdout;
  }

  async set(reference: string, value: string): Promise<void> {
    const path = this.secretPath(reference);
    await mkdir(this.root, { recursive: true, mode: 0o700 });
    const temporary = `${path}.tmp-${process.pid}-${randomBytes(6).toString("hex")}`;
    try {
      const result = await this.run("systemd-creds", ["encrypt", `--name=${reference}`, "-", temporary], value);
      if (result.code !== 0) throw new Error("node_identity_systemd_creds_encrypt_failed");
      await (await import("node:fs/promises")).chmod(temporary, 0o600);
      await rename(temporary, path);
    } finally {
      await rm(temporary, { force: true });
    }
  }

  async delete(reference: string): Promise<void> { await rm(this.secretPath(reference), { force: true }); }

  private secretPath(reference: string): string {
    assertSecretReference(reference);
    return join(this.root, `${reference}.cred`);
  }
}

const WINDOWS_DPAPI_SCRIPT = [
  "$ErrorActionPreference='Stop'",
  "Add-Type -AssemblyName System.Security",
  "$request=[Console]::In.ReadToEnd()|ConvertFrom-Json",
  "if($request.operation -eq 'protect') {",
  "  $plain=[Text.Encoding]::UTF8.GetBytes([string]$request.value)",
  "  $cipher=[Security.Cryptography.ProtectedData]::Protect($plain,$null,[Security.Cryptography.DataProtectionScope]::LocalMachine)",
  "  [IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName([string]$request.path))|Out-Null",
  "  $temporary=([string]$request.path)+'.tmp-'+[Guid]::NewGuid().ToString('N')",
  "  try {",
  "    [IO.File]::WriteAllBytes($temporary,$cipher)",
  "    if([IO.File]::Exists([string]$request.path)) {",
  "      [IO.File]::Replace($temporary,[string]$request.path,$null)",
  "    } else { [IO.File]::Move($temporary,[string]$request.path) }",
  "  } finally { if([IO.File]::Exists($temporary)) { [IO.File]::Delete($temporary) } }",
  "} elseif($request.operation -eq 'unprotect') {",
  "  if(-not [IO.File]::Exists([string]$request.path)) { exit 3 }",
  "  $cipher=[IO.File]::ReadAllBytes([string]$request.path)",
  "  $plain=[Security.Cryptography.ProtectedData]::Unprotect($cipher,$null,[Security.Cryptography.DataProtectionScope]::LocalMachine)",
  "  [Console]::Out.Write([Text.Encoding]::UTF8.GetString($plain))",
  "} else { throw 'unsupported operation' }",
].join(";");

export class WindowsDpapiSecretStore implements ProtectedSecretStore {
  readonly provider = "windows-dpapi-local-machine";
  private readonly root: string;

  constructor(
    root: string,
    private readonly run: SecretCommandRunner = runSecretCommand,
  ) {
    this.root = resolve(root);
  }

  async get(reference: string): Promise<string | null> {
    const result = await this.invoke("unprotect", reference);
    if (result.code === 3) return null;
    if (result.code !== 0) throw new Error("node_identity_dpapi_unprotect_failed");
    return result.stdout;
  }

  async set(reference: string, value: string): Promise<void> {
    const result = await this.invoke("protect", reference, value);
    if (result.code !== 0) throw new Error("node_identity_dpapi_protect_failed");
  }

  async delete(reference: string): Promise<void> {
    await rm(this.secretPath(reference), { force: true });
  }

  private async invoke(
    operation: "protect" | "unprotect",
    reference: string,
    value?: string,
  ): Promise<SecretCommandResult> {
    return await this.run(
      "powershell.exe",
      ["-NoLogo", "-NoProfile", "-NonInteractive", "-Command", WINDOWS_DPAPI_SCRIPT],
      JSON.stringify({ operation, path: this.secretPath(reference), ...(value === undefined ? {} : { value }) }),
    );
  }

  private secretPath(reference: string): string {
    assertSecretReference(reference);
    return join(this.root, `${reference}.dpapi`);
  }
}

export class MacOsKeychainSecretStore implements ProtectedSecretStore {
  readonly provider = "macos-keychain";

  constructor(private readonly run: SecretCommandRunner = runSecretCommand) {}

  async get(reference: string): Promise<string | null> {
    assertSecretReference(reference);
    const result = await this.run("/usr/bin/security", [
      "find-generic-password", "-a", reference, "-s", "mycellios.node.identity", "-w", "/Library/Keychains/System.keychain",
    ]);
    if (result.code === 44) return null;
    if (result.code !== 0) throw new Error("node_identity_keychain_lookup_failed");
    return result.stdout.replace(/\r?\n$/, "");
  }

  async set(reference: string, value: string): Promise<void> {
    assertSecretReference(reference);
    const command = [
      "add-generic-password -U",
      `-a ${shellQuote(reference)}`,
      "-s 'mycellios.node.identity'",
      `-w ${shellQuote(value)}`,
      "'/Library/Keychains/System.keychain'",
    ].join(" ");
    const result = await this.run("/usr/bin/security", ["-i"], `${command}\n`);
    if (result.code !== 0 || await this.get(reference) !== value) throw new Error("node_identity_keychain_store_failed");
  }

  async delete(reference: string): Promise<void> {
    assertSecretReference(reference);
    const result = await this.run("/usr/bin/security", [
      "delete-generic-password", "-a", reference, "-s", "mycellios.node.identity", "/Library/Keychains/System.keychain",
    ]);
    if (result.code !== 0 && result.code !== 44) {
      throw new Error("node_identity_keychain_delete_failed");
    }
  }
}

export async function deleteMacOsNodeIdentity(metadataPath: string, expectedIdentityId: string, run?: SecretCommandRunner): Promise<void> {
  const metadata = metadataSchema.parse(JSON.parse(await readFile(metadataPath, "utf8")) as unknown);
  if (metadata.identityId !== expectedIdentityId || metadata.provider !== "macos-keychain") {
    throw new Error("node_uninstall_macos_identity_mismatch");
  }
  await new MacOsKeychainSecretStore(run).delete(metadata.secretReference);
}

export async function runSecretCommand(
  executable: string,
  arguments_: readonly string[],
  stdin?: string,
): Promise<SecretCommandResult> {
  return await new Promise((resolve, reject) => {
    const child = spawn(executable, [...arguments_], {
      shell: false,
      stdio: ["pipe", "pipe", "ignore"],
      windowsHide: true,
    });
    const chunks: Buffer[] = [];
    child.stdout.on("data", (chunk: Buffer) => chunks.push(Buffer.from(chunk)));
    child.once("error", (error) => reject(new Error("node_identity_protected_store_unavailable", { cause: error })));
    child.once("close", (code) => resolve({ code: code ?? -1, stdout: Buffer.concat(chunks).toString("utf8") }));
    child.stdin.end(stdin ?? "");
  });
}

function assertSecretReference(reference: string): void {
  if (!/^[A-Za-z0-9._:-]{1,200}$/.test(reference)) {
    throw new Error("node_identity_secret_reference_is_invalid");
  }
}

function shellQuote(value: string): string {
  if (value.includes("\0") || value.includes("\n") || value.includes("\r")) {
    throw new Error("node_identity_keychain_value_is_invalid");
  }
  return `'${value.replaceAll("'", "'\\''")}'`;
}

export function serializeCredentialForProtectedStore(
  credential: WorkerAdmissionCredential,
): string {
  return JSON.stringify(parseWorkerAdmissionCredential(credential));
}

