let environment = headlessEnvironmentFromNodeConfiguration(config, version);
const componentLifecycle = config.componentUpdates
  ? new NodeComponentLifecycle(config, version, async () => true, async () => async () => undefined)
  : null;
let pendingComponentActivation = componentLifecycle
  ? await componentLifecycle.pendingActivationIsCurrent()
  : false;
if (componentLifecycle && !pendingComponentActivation && await componentLifecycle.pendingActivation()) {
  await componentLifecycle.markActivationHealthy();
}
const host = new MycelliosNodeServiceHost(join(dirname(configPath), "state"));
const controlStore = new NodeControlStateStore(join(host.stateDirectory, "control.json"));
await host.acquire(config.revision);
await assertNodeOsIsolation(config);
const controlState = await controlStore.load();

let agent: WorkerAgent | null = null;
let supervisorStopRequested = false;
let agentStarted = false;
const stopForSupervisor = () => {
  supervisorStopRequested = true;
  if (agentStarted) void agent?.stop();
};
process.on("message", (message: unknown) => {
  if (typeof message === "object" && message !== null && "type" in message
    && message.type === "mycellios-node-stop") stopForSupervisor();
});
process.once("disconnect", stopForSupervisor);
let governor: NodeResourceGovernor | null = null;
let commandClientAbort: AbortController | null = null;
let commandClient: Promise<void> | null = null;
let failure: unknown = null;
let lastIncident: { code: string; occurredAt: string } | null = null;
let componentInUseLease: ComponentInUseLease | null = null;
try {
  const activePythonProduct = await resolveNodePythonProduct(config);
  if (activePythonProduct && componentLifecycle) {
    componentInUseLease = await acquireComponentInUseLease(componentLifecycle.storageRoot, ["python-product"]);
    environment.pythonPath = componentInUseLease.roots["python-product"]!;
  }
  const accelerator = await prepareNativeNodeAccelerator({
    configPath,
    pythonProductPath: environment.pythonPath,
    installRoot: process.platform === "darwin" ? dirname(config.runtime.pythonPath) : dirname(dirname(config.runtime.pythonExecutable)),
    allowProvisioning: false,
  });
  environment = activateNativeNodeAccelerator(environment, accelerator);
  const runtime = await createNativeNodeRuntime(environment);
  const device = runtime.verifiedGpuRuntime ? runtime.physicalProbe.devices[0] : undefined;
  const detectedVramMiB = device
    ? Math.floor(Math.min(device.totalMemoryBytes, device.runtimeTotalMemoryBytes) / (1024 * 1024))
    : 0;
  const offeredMemoryMiB = device
    ? Math.min(detectedVramMiB, config.limits.maxVramMiB || detectedVramMiB)
    : Math.max(512, Math.floor(config.limits.maxRamMiB / 2));
  const workerConfig = loadWorkerConfig(environment.configPath);
  const admissionSigner = await new NodeIdentityStore(
    config.coordinator.identityPath,
    platformSecretStore(),
    { allowLegacyMigration },
  ).loadOrCreate(config.nodeId);
  const enrollmentBootstrap = new NodeEnrollmentBootstrap(
    argument("--enrollment-file") ?? join(dirname(configPath), "enrollment.json"),
    config.coordinator.url,
  );
  agent = new WorkerAgent({
    ...workerConfig,
    offeredVramMb: offeredMemoryMiB,
    limits: {
      ...workerConfig.limits,
      maxConcurrency: Math.min(workerConfig.limits.maxConcurrency, config.limits.maxConcurrency),
    },
  }, {
    coordinatorUrl: environment.coordinatorUrl,
    identity: { kind: "device", id: config.nodeId },
    admissionSigner,
    beforeSignedAdmission: (input) => enrollmentBootstrap.redeem(input),
    reconnect: true,
    advertiseDeployment: false,
    agentVersion: version,
    ...(runtime.verifiedGpuRuntime ? { verifiedGpuRuntime: runtime.verifiedGpuRuntime } : {}),
    ...(runtime.preferredHardwareGpu ? { preferredHardwareGpu: runtime.preferredHardwareGpu } : {}),
    ...(device && runtime.preferredHardwareGpu ? { hardwareCapacityOverride: {
      id: `physical-${device.index}`,
      vendor: runtime.preferredHardwareGpu.vendor,
      model: device.name,
      physicalVramMb: runtime.verifiedGpuRuntime?.backend === "directml" && runtime.preferredHardwareGpu.vendor === "intel" ? 0 : detectedVramMiB,
      ...(runtime.verifiedGpuRuntime?.backend === "directml" && runtime.preferredHardwareGpu.vendor === "intel" ? { sharedMemoryMb: detectedVramMiB, unifiedMemory: true } : {}),
    } } : {}),
    distributedExecutor: runtime.executor,
    runtimePerformanceProfileProbe: () => probeRuntimePerformanceProfile({
      pythonExecutable: environment.pythonExecutable,
      pythonPath: [environment.pythonPath],
      backend: runtime.verifiedGpuRuntime?.backend ?? "cpu",
      device: runtime.verifiedGpuRuntime ? accelerator.launchDevice : "cpu",
      precision: runtime.verifiedGpuRuntime ? accelerator.precision : "float32",
      ...(runtime.verifiedGpuRuntime ? { expectedDeviceName: runtime.verifiedGpuRuntime.deviceName } : {}),
      cwd: process.cwd(),
      env: { HF_HOME: environment.cachePath },
    }),
    contributionControl: {
      initialEnabled: controlState.contributionEnabled && !controlState.draining,
      onRemoteChange: async (enabled) => { await controlStore.setContributionEnabled(enabled); },
    },
    workAdmissionPolicy: (model, at) => evaluateNodeWorkPolicy(config.policy ?? DEFAULT_NODE_WORK_POLICY, model, at),
  });
  const resourceObserver = createNodeResourceObserver(config.runtime.cachePath);
  const snapshotResourceObserver = createNodeResourceObserver(config.runtime.cachePath);
  governor = new NodeResourceGovernor(
    config.limits,
    resourceObserver,
    async (code) => {
      failure = new Error(code);
      lastIncident = { code, occurredAt: new Date().toISOString() };
      await host.writeHealth("failed", config.revision, code);
      await controlStore.setContributionEnabled(false);
      await agent?.setContributionEnabled(false).catch(() => undefined);
      await agent?.stop();
    },
  );
  for (const signal of ["SIGINT", "SIGTERM"] as const) {
    process.once(signal, () => void agent?.stop());
  }
  const running = agent.start();
  agentStarted = true;
  if (supervisorStopRequested) void agent.stop();
  await waitUntil(() => agent?.isReady === true, running, 60_000);
  const uninstall = config.uninstall
    ? new NodeUninstallScheduler(config.uninstall.manifestPath, join(host.stateDirectory, "uninstall-requests"))
    : undefined;
  const commandApplicator = new NodeCommandApplicator(agent, controlStore, store, config, componentLifecycle ?? undefined, uninstall);
  if (controlState.draining) await commandApplicator.restoreDrain();
  await host.writeHealth("ready", config.revision);
  await writeNodeDiagnosticSnapshot(
    join(host.stateDirectory, "diagnostics.json"),
    buildNodeDiagnosticSnapshot({
      config,
      version,
      state: "ready",
      physicalProbe: runtime.physicalProbe,
    }),
  );
  governor.start();
  if (pendingComponentActivation && componentLifecycle) {
    await componentLifecycle.markActivationHealthy();
    pendingComponentActivation = false;
    await controlStore.setDraining(false);
    if (controlState.contributionEnabled) await agent.setContributionEnabled(true);
  }
  const controlSession = agent.nodeControlSession;
  if (controlSession) {
    commandClientAbort = new AbortController();
    const commandExecutor = new NodeCommandExecutor(
      join(host.stateDirectory, `commands-generation-${controlSession.generation}.json`),
      config.nodeId,
      controlSession.generation,
    );
    const reconciliationState = new NodeReconciliationStateStore(
      join(host.stateDirectory, "reconciliation.json"),
      config.nodeId,
    );
    let restartAfterReconciliation = false;
    commandClient = runNodeCommandClient({
      coordinatorUrl: environment.coordinatorUrl,
      nodeId: config.nodeId,
      session: () => agent?.nodeControlSession ?? null,
      executor: commandExecutor,
      apply: async (application) => commandApplicator.apply(application),
      signal: commandClientAbort.signal,
      reconciliation: {
        state: reconciliationState,
        snapshot: async (cursor, session) => {
          const [currentControl, currentConfig, journal, resourceObservation] = await Promise.all([
            controlStore.load(),
            store.load(),
            commandExecutor.inspect(),
            snapshotResourceObserver().catch(() => null),
          ]);
          const resourceViolation = resourceObservation ? breachedLimit(currentConfig.config.limits, resourceObservation) : "node_resource_probe_failed";
          const incident = lastIncident ?? (resourceViolation ? { code: resourceViolation, occurredAt: new Date().toISOString() } : null);
          return {
            schema: "mycellios-node-snapshot/1",
            nodeId: config.nodeId,
            generation: session.generation,
            cursor,
            observedAt: new Date().toISOString(),
            state: incident ? "degraded" : agent?.isReady ? "ready" : "reconnecting",
            contributionEnabled: currentControl.contributionEnabled,
            draining: currentControl.draining,
            updateChannel: currentConfig.config.updateChannel,
            limits: currentConfig.config.limits,
            policy: currentConfig.config.policy ?? DEFAULT_NODE_WORK_POLICY,
            activeCommandIds: journal.records.filter(({ state }) => state === "applying").map(({ commandId }) => commandId),
            build: { version, sourceRevision },
            runtime: { ready: agent?.isReady === true, abi: MYCELLIOS_RUNTIME_ABI, backend: runtime.verifiedGpuRuntime?.backend ?? "cpu",
              uninstallAvailable: config.uninstall !== undefined },
            diagnostics: {
              capturedAt: new Date().toISOString(),
              configRevision: currentConfig.config.revision,
              capacity: {
                acceleratorCount: runtime.physicalProbe.devices.length,
                primaryAccelerator: device ? { name: device.name, totalMemoryMiB: detectedVramMiB,
                  offeredMemoryMiB: Math.min(detectedVramMiB, currentConfig.config.limits.maxVramMiB || detectedVramMiB) } : null,
              },
              resources: resourceObservation ? { ...resourceObservation, healthy: resourceViolation === null, violation: resourceViolation } : null,
              incident,
            },
          };
        },
        onReconciled: async ({ desiredState, acknowledgedCommandIds }) => {
          if (uninstall && await uninstall.armAcknowledged(new Set(acknowledgedCommandIds)) > 0) {
            await agent?.stop();
            return;
          }
          const currentControl = await controlStore.load();
          if (desiredState.drain !== currentControl.draining) await commandApplicator.reconcileDrain(desiredState.drain);
          if (currentControl.contributionEnabled !== desiredState.contributionEnabled) {
            await controlStore.setContributionEnabled(desiredState.contributionEnabled);
          }
          await agent?.setContributionEnabled(desiredState.contributionEnabled && !desiredState.drain);
          const current = await store.load();
          const limitsChanged = JSON.stringify(current.config.limits) !== JSON.stringify(desiredState.limits);
          const policyChanged = JSON.stringify(current.config.policy) !== JSON.stringify(desiredState.policy);
          if (limitsChanged || policyChanged || current.config.updateChannel !== desiredState.updateChannel) {
            await store.save({
              ...current.config,
              revision: current.config.revision + 1,
              limits: desiredState.limits,
              policy: desiredState.policy ?? DEFAULT_NODE_WORK_POLICY,
              updateChannel: desiredState.updateChannel,
            });
            restartAfterReconciliation = true;
          }
        },
        onSnapshotAcknowledged: async () => {
          lastIncident = null;
          if (restartAfterReconciliation) await agent?.stop();
        },
      },
      onError: (error) => {
        const code = safeIncidentCode(error instanceof Error ? error.message : "node_command_client_error");
        lastIncident = { code, occurredAt: new Date().toISOString() };
        void host.writeHealth("ready", config.revision, code).catch(() => undefined);
      },
      onAcknowledged: async (command, result) => {
        if (result.state === "applied" && (commandApplicator.takeRestartAfterAck(command.id) || await commandApplicator.armStopAfterAck(command.id))) {
          await agent?.stop();
        }
      },
    });
  }
  await running;
} catch (error) {
  failure = error;
  if (pendingComponentActivation && componentLifecycle) {
    try {
      await componentLifecycle.rollbackFailedActivation();
      pendingComponentActivation = false;
    } catch (rollbackError) {
      failure = new AggregateError([error, rollbackError], "node_component_activation_and_rollback_failed");
    }
  }
  throw failure;
} finally {
  commandClientAbort?.abort();
  await commandClient?.catch(() => undefined);
  governor?.stop();
  await agent?.stop().catch(() => undefined);
  await componentInUseLease?.release().catch(() => undefined);
  try {
    await host.release(
      config.revision,
      failure ? "failed" : "stopped",
      failure instanceof Error ? failure.message : failure ? String(failure) : undefined,
    );
  } finally {
    // The supervisor owns an IPC channel. Disconnect after shutdown so a
    // completed child cannot stay alive and prevent the supervisor restart.
    if (process.connected) process.disconnect();
  }
}

function argument(name: string): string | undefined {
  const index = process.argv.indexOf(name);
  return index >= 0 ? process.argv[index + 1] : undefined;
}

function defaultNodeConfigurationPath(): string {
  if (process.platform === "win32") {
    const root = process.env.PROGRAMDATA;
    if (!root) throw new Error("mycellios_node_programdata_is_missing");
    return join(root, "mycellios", "node.json");
  }
  if (process.platform === "darwin") return "/Library/Application Support/mycellios/node.json";
  return "/etc/mycellios/node.json";
}

async function waitUntil(
  predicate: () => boolean,
  running: Promise<void>,
  timeoutMs: number,
): Promise<void> {
  const deadline = Date.now() + timeoutMs;
  while (!predicate()) {
    if (Date.now() >= deadline) throw new Error("mycellios_node_ready_timeout");
    await Promise.race([
      running.then(() => { throw new Error("mycellios_node_stopped_before_ready"); }),
      new Promise<void>((resolve) => setTimeout(resolve, 100)),
    ]);
  }
}

function packageVersion(): string {
  const document = JSON.parse(
    readFileSync(new URL("../../package.json", import.meta.url), "utf8"),
  ) as { version?: unknown };
  if (typeof document.version !== "string" || !document.version.trim()) {
    throw new Error("mycellios_node_package_version_is_invalid");
  }
  return document.version;
}

function platformSecretStore(): ProtectedSecretStore {
  if (process.platform === "linux") return new LinuxSystemdCredentialStore(
    join(dirname(config.coordinator.identityPath), "protected"),
  );
  if (process.platform === "darwin") return new MacOsKeychainSecretStore();
  if (process.platform === "win32") {
    const root = process.env.PROGRAMDATA;
    if (!root) throw new Error("mycellios_node_programdata_is_missing");
    return new WindowsDpapiSecretStore(join(root, "mycellios", "protected-identity"));
  }
  throw new Error(`mycellios_node_protected_identity_backend_is_unsupported:${process.platform}`);
}

function safeIncidentCode(value: string): string {
  const code = value.match(/^[a-zA-Z0-9_.:-]{1,120}/)?.[0];
  if (!code || /(authorization|cookie|credential|password|secret|token|api[-_]?key)/i.test(code) || /[A-Za-z0-9_-]{32,}/.test(code)) {
    return "unclassified_error";
  }
  return code;
}

import { spawn } from "node:child_process";
import { constants, copyFile, lstat, mkdir, open, writeFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import type { NodeConfiguration } from "../contracts/node-configuration.js";
import type { NodeInstallationManifest } from "../contracts/node-uninstall.js";
import { linuxSystemdServiceDefinition, macOsLaunchdServiceDefinition } from "./service-definition.js";

export interface ServiceCommandResult { code: number; stdout: string }
export type ServiceCommandRunner = (executable: string, arguments_: readonly string[]) => Promise<ServiceCommandResult>;

export async function registerNativeNodeService(input: {
  manifest: NodeInstallationManifest;
  config: NodeConfiguration;
  run?: ServiceCommandRunner;
  replaceRetainedServiceFiles?: boolean;
}): Promise<void> {
  const run = input.run ?? runServiceCommand;
  const { manifest, config } = input;
  const serviceEntrypoint = join(dirname(manifest.helperEntrypoint), "main.js");
  if (manifest.platform === "linux") {
    const definition = linuxSystemdServiceDefinition({ config, configPath: manifest.configPath,
      nodeExecutable: manifest.nodeExecutable, serviceEntrypoint });
    await writeNewServiceDefinition(manifest.serviceDefinitionPath, definition);
    const user = await run("/usr/sbin/useradd", ["--system", "--user-group", "--home-dir", "/nonexistent", "--shell", "/usr/sbin/nologin", "mycellios"]);
    if (user.code !== 0 && user.code !== 9) throw new Error("node_service_user_creation_failed");
    await requireSuccess(run, "/bin/chown", ["-R", "mycellios:mycellios", dirname(manifest.configPath), dirname(manifest.identityPath), manifest.cachePath, manifest.logsPath, manifest.statePath], "node_service_permissions_failed");
    await requireSuccess(run, "/bin/systemctl", ["daemon-reload"], "node_service_manager_reload_failed");
    await requireSuccess(run, "/bin/systemctl", ["enable", "--now", manifest.serviceName], "node_service_start_failed");
    return;
  }
  if (manifest.platform === "darwin") {
    const writable = [dirname(manifest.configPath), dirname(manifest.identityPath), manifest.cachePath, manifest.logsPath, manifest.statePath];
    for (const directory of writable) {
      await mkdir(directory, { recursive: true, mode: 0o700 });
      const entry = await lstat(directory);
      if (!entry.isDirectory() || entry.isSymbolicLink()) throw new Error("node_service_directory_is_unsafe");
    }
    const definition = macOsLaunchdServiceDefinition({ config, configPath: manifest.configPath,
      nodeExecutable: manifest.nodeExecutable, serviceEntrypoint, label: manifest.serviceName });
    await writeNewServiceDefinition(manifest.serviceDefinitionPath, definition);
    await requireSuccess(run, "/usr/sbin/chown", ["-R", "root:wheel", dirname(manifest.configPath), dirname(manifest.identityPath), manifest.cachePath, manifest.logsPath, manifest.statePath], "node_service_permissions_failed");
    await requireSuccess(run, "/bin/launchctl", ["bootstrap", "system", manifest.serviceDefinitionPath], "node_service_registration_failed");
    await requireSuccess(run, "/bin/launchctl", ["enable", `system/${manifest.serviceName}`], "node_service_enable_failed");
    await requireSuccess(run, "/bin/launchctl", ["kickstart", "-k", `system/${manifest.serviceName}`], "node_service_start_failed");
    return;
  }
  if (manifest.platform === "win32") {
    if (input.replaceRetainedServiceFiles) {
      const existing = await run("sc.exe", ["query", manifest.serviceName]);
      if (existing.code !== 1060) throw new Error("node_service_must_be_absent_for_restore");
    }
    const supervisedEntrypoint = join(dirname(manifest.helperEntrypoint), "service-supervisor.js");
    const serviceDirectory = dirname(manifest.serviceDefinitionPath);
    const wrapperSource = join(manifest.installRoot, "bin", "MycelliosNode.exe");
    const wrapperTarget = join(serviceDirectory, "MycelliosNode.exe");
    if (manifest.serviceDefinitionPath !== join(serviceDirectory, "MycelliosNode.xml")) {
      throw new Error("node_service_definition_path_is_invalid");
    }
    const protectedIdentity = join(dirname(dirname(manifest.configPath)), "protected-identity");
    const writable = [dirname(manifest.configPath), dirname(manifest.identityPath), protectedIdentity,
      manifest.cachePath, manifest.logsPath, manifest.statePath];
    for (const path of [...writable, serviceDirectory]) await mkdir(path, { recursive: true });
    for (const path of writable) {
      await requireSuccess(run, "icacls.exe", [path, "/inheritance:r", "/grant:r", "*S-1-5-18:(OI)(CI)F", "/grant:r", "*S-1-5-32-544:(OI)(CI)F", "/grant:r", "*S-1-5-19:(OI)(CI)M"], "node_service_permissions_failed");
    }
    const pendingPath = join(dirname(manifest.configPath), "enrollment.json");
    const pending = !input.replaceRetainedServiceFiles || await lstat(pendingPath).then(() => true, (error: NodeJS.ErrnoException) => {
      if (error.code === "ENOENT") return false; throw error;
    });
    const protectedFiles = [manifest.configPath, config.worker.configPath,
      ...(pending ? [pendingPath] : []),
      join(manifest.statePath, "installation.json")];
    for (const path of protectedFiles) {
      await requireSuccess(run, "icacls.exe", [path, "/inheritance:r", "/grant:r", "*S-1-5-18:F", "/grant:r", "*S-1-5-32-544:F", "/grant:r", "*S-1-5-19:M"], "node_service_permissions_failed");
    }
    await requireSuccess(run, "icacls.exe", [serviceDirectory, "/inheritance:r", "/grant:r", "*S-1-5-18:(OI)(CI)F", "/grant:r", "*S-1-5-32-544:(OI)(CI)F", "/grant:r", "*S-1-5-19:(OI)(CI)RX"], "node_service_permissions_failed");
    await copyFile(wrapperSource, wrapperTarget, input.replaceRetainedServiceFiles ? 0 : constants.COPYFILE_EXCL);
    const definition = windowsServiceDefinition({ manifest, serviceEntrypoint: supervisedEntrypoint });
    if (input.replaceRetainedServiceFiles) await writeFile(manifest.serviceDefinitionPath, definition, "utf8");
    else await writeNewServiceDefinition(manifest.serviceDefinitionPath, definition);
    await requireSuccess(run, "sc.exe", ["create", manifest.serviceName, "binPath=", `"${wrapperTarget}"`, "start=", "auto", "obj=", "NT AUTHORITY\\LocalService"], "node_service_registration_failed");
    await requireSuccess(run, "sc.exe", ["failure", manifest.serviceName, "reset=", "86400", "actions=", "restart/5000/restart/15000/none/0"], "node_service_recovery_policy_failed");
    await requireSuccess(run, "sc.exe", ["start", manifest.serviceName], "node_service_start_failed");
    return;
  }
  const exhaustive: never = manifest.platform;
  throw new Error(`node_service_platform_is_unsupported:${exhaustive}`);
}

function windowsServiceDefinition(input: { manifest: NodeInstallationManifest; serviceEntrypoint: string }): string {
  const { manifest, serviceEntrypoint } = input;
  for (const value of [manifest.nodeExecutable, serviceEntrypoint, manifest.configPath, manifest.logsPath]) {
    if (/[\r\n\0"]/.test(value)) throw new Error("node_service_path_is_invalid");
  }
  const escaped = (value: string) => value.replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;").replaceAll('"', "&quot;");
  return ["<service>", `  <id>${escaped(manifest.serviceName)}</id>`,
    "  <name>Mycellios Node</name>", "  <description>Mycellios native inference node</description>",
    `  <executable>${escaped(manifest.nodeExecutable)}</executable>`,
    `  <arguments>${escaped(`"${serviceEntrypoint}" --config "${manifest.configPath}"`)}</arguments>`,
    `  <workingdirectory>${escaped(manifest.installRoot)}</workingdirectory>`,
    `  <logpath>${escaped(manifest.logsPath)}</logpath>`,
    "  <log mode=\"roll\" />", "</service>", ""].join("\n");
}

async function writeNewServiceDefinition(path: string, value: string): Promise<void> {
  await mkdir(dirname(path), { recursive: true });
  const file = await open(path, "wx", 0o644);
  try { await file.writeFile(value, "utf8"); await file.sync(); }
  finally { await file.close(); }
}

async function requireSuccess(run: ServiceCommandRunner, executable: string, arguments_: readonly string[], error: string): Promise<void> {
  const result = await run(executable, arguments_);
  if (result.code !== 0) throw new Error(error);
}

export async function runServiceCommand(executable: string, arguments_: readonly string[]): Promise<ServiceCommandResult> {
  return await new Promise((resolve, reject) => {
    const child = spawn(executable, [...arguments_], { shell: false, windowsHide: true, stdio: ["ignore", "pipe", "ignore"] });
    const chunks: Buffer[] = [];
    child.stdout.on("data", (chunk: Buffer) => chunks.push(Buffer.from(chunk)));
    child.once("error", (error) => reject(new Error("node_service_manager_is_unavailable", { cause: error })));
    child.once("close", (code) => resolve({ code: code ?? -1, stdout: Buffer.concat(chunks).toString("utf8") }));
  });
}

import { constants, lstat, open, readFile, rename, rm } from "node:fs/promises";
import { deleteMacOsNodeIdentity } from "./identity-store.js";
import { dirname } from "node:path";
import { execFile, spawn } from "node:child_process";
import { mkdir } from "node:fs/promises";
import { nodeUninstallReceiptSchema, type NodeInstallationManifest, type NodeUninstallReceipt, type NodeUninstallRequest } from "../contracts/node-uninstall.js";

export type PlatformCommandRunner = (executable: string, args: readonly string[], allowFailure?: boolean) => Promise<void>;
export type PathRemover = (path: string) => Promise<void>;

export async function executeVerifiedUninstall(input: {
  request: NodeUninstallRequest;
  manifest: NodeInstallationManifest;
  requestDigest: string;
  run?: PlatformCommandRunner;
  remove?: PathRemover;
  now?: () => Date;
}): Promise<NodeUninstallReceipt> {
  const existing = await readReceipt(input.manifest.receiptPath);
  if (existing) {
    if (existing.requestId !== input.request.id || existing.requestDigest !== input.requestDigest) {
      throw new Error("node_uninstall_receipt_conflict");
    }
    return existing;
  }
  const run = input.run ?? runPlatformCommand;
  const packagedMac = input.manifest.platform === "darwin" &&
    input.manifest.installRoot === "/Library/Application Support/Mycellios/Product" &&
    input.manifest.serviceName === "io.mycellios.node";
  if (packagedMac && (input.manifest.configPath !== "/Library/Application Support/Mycellios/Configuration/node.json" ||
      input.manifest.identityPath !== "/Library/Application Support/Mycellios/Identity/node.json")) {
    throw new Error("node_uninstall_macos_default_data_paths_mismatch");
  }
  const pairingPresent = packagedMac ? await validateMacPairingApplication(input.manifest.installRoot) : false;
  const receiptPresent = packagedMac ? await macPackageReceiptPresent() : false;
  await disableService(input.manifest, run);
  if (receiptPresent) await run("/usr/sbin/pkgutil", ["--forget", "io.mycellios.node"]);
  if (packagedMac && !input.request.retain.identity) {
    await deleteMacOsNodeIdentity(input.manifest.identityPath, input.request.nodeId);
  }
  const remove = input.remove ?? (async (path) => rm(path, { recursive: true, force: true }));
  const selected = new Set<string>([input.manifest.platform === "win32"
    ? dirname(input.manifest.serviceDefinitionPath) : input.manifest.serviceDefinitionPath]);
  if (!input.request.retain.configuration) selected.add(input.manifest.configPath);
  if (!input.request.retain.identity) selected.add(input.manifest.identityPath);
  if (!input.request.retain.cache) selected.add(input.manifest.cachePath);
  if (!input.request.retain.logs) selected.add(input.manifest.logsPath);
  if (packagedMac && !input.request.retain.configuration) selected.add(dirname(input.manifest.configPath));
  if (packagedMac && !input.request.retain.identity) selected.add(dirname(input.manifest.identityPath));
  selected.add(input.manifest.statePath);
  for (const path of [...selected].sort((left, right) => right.length - left.length)) await remove(path);
  if (pairingPresent) await remove("/Applications/Mycellios Pairing.app");
  await remove(input.manifest.installRoot);
  if (input.manifest.platform === "linux") await run("systemctl", ["daemon-reload"]);
  const receipt = nodeUninstallReceiptSchema.parse({
    schema: "mycellios-node-uninstall-receipt/1",
    requestId: input.request.id,
    requestDigest: input.requestDigest,
    state: "completed",
    platform: input.manifest.platform,
    retained: Object.entries(input.request.retain).filter(([, retained]) => retained).map(([name]) => name),
    createdAt: (input.now ?? (() => new Date()))().toISOString(),
  });
  await writeReceipt(input.manifest.receiptPath, receipt);
  return receipt;
}

async function validateMacPairingApplication(product: string): Promise<boolean> {
  const app = "/Applications/Mycellios Pairing.app";
  const stats = await lstat(app).catch((error: NodeJS.ErrnoException) => {
    if (error.code === "ENOENT") return null; throw error;
  });
  if (stats === null) return false;
  for (const path of [app, `${app}/Contents`, `${app}/Contents/MacOS`]) {
    const entry = path === app ? stats : await lstat(path);
    if (!entry.isDirectory() || entry.isSymbolicLink()) throw new Error(`node_uninstall_macos_pairing_unsafe:${path}`);
  }
  const plist = await readMacPairingFile(`${app}/Contents/Info.plist`);
  const applet = plist.includes("<string>droplet</string>");
  if (applet) {
    for (const path of [`${app}/Contents/Resources`, `${app}/Contents/Resources/Scripts`]) {
      const entry = await lstat(path);
      if (!entry.isDirectory() || entry.isSymbolicLink()) throw new Error("node_uninstall_macos_pairing_unsafe");
    }
  }
  const launcher = await readMacPairingFile(`${app}/Contents/${applet ? "Resources" : "MacOS"}/pair-mycellios`);
  const expectedBridge = ["#!/bin/sh", "set -eu", `exec "${product}/bin/node" "${product}/app/node/macos-pairing-main.js" "$1"`, ""].join("\n");
  if (!plist.includes("<string>io.mycellios.pairing</string>") ||
      launcher !== expectedBridge) {
    throw new Error("node_uninstall_macos_pairing_mismatch");
  }
  if (applet) {
    await readMacPairingFile(`${app}/Contents/MacOS/droplet`, 1_048_576);
    await readMacPairingFile(`${app}/Contents/Resources/Scripts/main.scpt`, 65_536);
    await pairingApplicationTool("/usr/bin/codesign", ["--verify", "--strict", "--deep", app]);
    const source = await pairingApplicationTool("/usr/bin/osadecompile", [`${app}/Contents/Resources/Scripts/main.scpt`]);
    const expected = "on open incomingDocuments\nrepeat with incomingDocument in incomingDocuments\ndo shell script \"'/Applications/Mycellios Pairing.app/Contents/Resources/pair-mycellios' \" & quoted form of POSIX path of incomingDocument\nend repeat\nquit\nend open";
    const normalize = (value: string): string => value.split(/\r?\n/).map(line => line.trim()).filter(Boolean).join("\n");
    if (normalize(source) !== expected) throw new Error("node_uninstall_macos_pairing_mismatch");
  } else if (!plist.includes("<string>pair-mycellios</string>")) {
    throw new Error("node_uninstall_macos_pairing_mismatch");
  }
  return true;
}

async function pairingApplicationTool(file: string, args: string[]): Promise<string> {
  return await new Promise((resolve, reject) => execFile(file, args,
    { encoding: "utf8", timeout: 30_000, maxBuffer: 8192 }, (error, stdout) => {
      if (error) reject(new Error("node_uninstall_macos_pairing_invalid", { cause: error }));
      else resolve(stdout);
    }));
}

async function readMacPairingFile(path: string, maximumBytes = 8192): Promise<string> {
  const file = await open(path, constants.O_RDONLY | constants.O_NOFOLLOW);
  try {
    const stats = await file.stat();
    if (!stats.isFile() || stats.size > maximumBytes) throw new Error("node_uninstall_macos_pairing_file_unsafe");
    const buffer = Buffer.alloc(maximumBytes + 1);
    const { bytesRead } = await file.read(buffer, 0, buffer.length, 0);
    if (bytesRead > maximumBytes) throw new Error("node_uninstall_macos_pairing_file_unsafe");
    return buffer.subarray(0, bytesRead).toString("utf8");
  } finally { await file.close(); }
}

async function macPackageReceiptPresent(): Promise<boolean> {
  return await new Promise((resolve, reject) => {
    execFile("/usr/sbin/pkgutil", ["--pkg-info", "io.mycellios.node"],
      { encoding: "utf8", timeout: 30_000, maxBuffer: 8192, env: { ...process.env, LC_ALL: "C" } },
      (error, stdout, stderr) => {
        if (!error) { resolve(true); return; }
        if (error.code === 1 && !error.killed &&
            /^No receipt for 'io\.mycellios\.node' found at '\/'\.\s*$/.test((stdout + stderr).trim())) {
          resolve(false); return;
        }
        reject(new Error("node_uninstall_macos_receipt_query_failed", { cause: error }));
      });
  });
}

async function disableService(manifest: NodeInstallationManifest, run: PlatformCommandRunner): Promise<void> {
  if (manifest.platform === "linux") {
    await run("systemctl", ["disable", "--now", manifest.serviceName], true);
    return;
  }
  if (manifest.platform === "darwin") {
    await run("launchctl", ["bootout", `system/${manifest.serviceName}`], true);
    return;
  }
  await run("sc.exe", ["stop", manifest.serviceName], true);
  await run("sc.exe", ["delete", manifest.serviceName], true);
}

async function runPlatformCommand(executable: string, args: readonly string[], allowFailure = false): Promise<void> {
  const child = spawn(executable, [...args], { shell: false, windowsHide: true, stdio: "ignore" });
  const code = await new Promise<number>((resolve, reject) => {
    child.once("error", reject);
    child.once("exit", (status) => resolve(status ?? -1));
  });
  if (code !== 0 && !allowFailure) throw new Error(`node_uninstall_service_command_failed:${executable}:${code}`);
}

async function readReceipt(path: string): Promise<NodeUninstallReceipt | null> {
  try { return nodeUninstallReceiptSchema.parse(JSON.parse(await readFile(path, "utf8"))); }
  catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") return null;
    throw error;
  }
}

async function writeReceipt(path: string, receipt: NodeUninstallReceipt): Promise<void> {
  await mkdir(dirname(path), { recursive: true, mode: 0o700 });
  const temporary = `${path}.tmp-${process.pid}`;
  const file = await open(temporary, "wx", 0o600);
  try { await file.writeFile(`${JSON.stringify(receipt, null, 2)}\n`, "utf8"); await file.sync(); } finally { await file.close(); }
  await rename(temporary, path);
}

